// Capítulo 3 da Unidade 1 — "Posto... logo, existo!" (artigo de opinião "Selfies", pronome relativo,
// E ou I / O ou U, confronto de pontos de vista e artigo de opinião II).
//
// Cada pergunta ou item do livro virou exatamente uma atividade de múltipla escolha (A, B, C ou D).
// Os textos-base foram reescritos com palavras nossas. As tiras ganharam ilustrações novas, com
// personagens e falas originais que mantêm a mesma ideia e a mesma construção das frases.
// Produções de texto longas (artigo de opinião, comparação de textos, jornal do Intervalo) não viram questão.

const IMG_PLACEBO = `${IMG}/c3-placebo.jpg`;
const IMG_RELOGIO = `${IMG}/c3-relogio.jpg`;
const IMG_GATO = `${IMG}/c3-gato-meia-noite.jpg`;
const IMG_FRASE = `${IMG}/c3-frase-coracao.jpg`;
const IMG_CASULO = `${IMG}/c3-casulo.jpg`;
const IMG_DESEMPREGO = `${IMG}/c3-desemprego.jpg`;
const IMG_CHEFE = `${IMG}/c3-sinonimos-chefe.jpg`;
const IMG_ALIEN = `${IMG}/c3-alienigena.jpg`;

const INSTR = "Toque na resposta certa";
const Q = (
  id: string,
  pergunta: string,
  certa: string,
  erradas: [string, string, string],
  dif: "easy" | "medium" | "hard" = "easy"
): Activity => mc(id, pergunta, INSTR, certa, erradas, dif);

// Texto-base "Selfies" (reescrito). É usado em dois grupos.
const CRED_SELFIES = "Baseado em Marcelo Coelho, “Selfies”, Folha de S.Paulo, 23 abr. 2014.";
const selfiesTexto = (id: string): Activity =>
  read(
    id,
    "Selfies",
    [
      "Há muita gente irritada com o uso sem limites dos celulares — e com razão. Se eles servissem só para falar, já seria ruim, mas também tiram fotos, e por isso somos invadidos por imagens de gatos escalando a cortina, de focinhos de cachorro diante da câmera e de pratos de torresmo, brownie e feijoada.",
      "Se depender do que vejo com meus filhos, de dez e doze anos, o tempo das selfies está chegando ao fim. Eles já acham ridícula a mania de fotografar o próprio rosto em qualquer ocasião, e isso virou até motivo de preconceito entre os colegas: “Fulaninha? Só vive tirando foto no espelho.” O hábito, porém, pode ser compreensível. Pense em alguém que treina para melhorar o corpo e registra o progresso a cada semana, ou em um adolescente que está começando a descobrir quem é.",
      "A bobeira aparece em outras cenas: a pessoa que faz uma selfie com a torre Eiffel ao fundo ou, pior, ao lado de, sei lá, um ator famoso. Se fosse apenas o registro de algo importante que nos acontece, tudo bem. O caso das fotos de comida é mais complicado. Vejo nisso uma espécie de degradação da experiência: o que vivemos de verdade, como uma estadia em Paris ou um jantar num restaurante, deixa de ser vivido e sentido como realmente é.",
      "Se, em vez de simplesmente viajar, eu me entrego a fotografar a mim mesmo, posso estar fugindo das minhas próprias sensações. É como se eu dividisse meu “self” (a palavra cabe bem) em duas pessoas: a que está em Paris e a que fotografa quem está em Paris.",
      "Pode ser narcisismo, é claro. Mas o narcisismo não precisa viajar para lugar nenhum. O que me incomoda é a torre Eiffel: o que fazer da minha relação com ela? Eu poderia me unir à paisagem, sentir como respiro diante daquela enorme elevação de ferro e nuvem, deixar meu olhar atravessar o duro rendilhado de metal que brilha ao sol, fazer-me pequeno sob as quatro vigas curvas. Fico um tempo parado, no meio de turistas, ruídos e crianças.",
      "Então pego o celular e tiro uma selfie. O mundo cabe todo na tela do aparelho. Não por acaso, faço uma careta idiota; viro de costas para o monumento, mas, na verdade, estou virando as costas para a vida.",
      "Talvez as coisas não sejam tão desesperadoras. Imagine que, daqui a cem anos, depois de uma guerra atômica e de uma catástrofe climática que destruam o mundo civilizado, um pesquisador encontre as selfies e as fotos de batata frita. Ele pode pensar: “Como as pessoas eram felizes naquela época!”. Ou: “Como eram tontas!”. Vai depender do humor dele.",
      "Vocabulário: narcisismo é o amor pela própria imagem; self é uma palavra de origem inglesa que significa “si mesmo”.",
    ],
    CRED_SELFIES
  );

